<?php defined('BASEPATH') or exit('No direct script access allowed'); init_head(); ?><div id="wrapper"><div class="content"><div class="panel_s"><div class="panel-body"><?php $this->load->view('usi_smartchoice_seo/partials/top'); ?><h4><?php echo html_escape($title); ?></h4><?php echo form_open(admin_url('usi_smartchoice_seo/video_voice/' . (int)($voice['id'] ?? 0))); ?><?php echo render_input('voice_name', 'Voice Name', $voice['voice_name'] ?? ''); ?><div class="row"><div class="col-md-4"><?php echo render_input('language', 'Language', $voice['language'] ?? 'en-US'); ?></div><div class="col-md-4"><?php echo render_select('gender', [['id'=>'male','name'=>'Male'],['id'=>'female','name'=>'Female'],['id'=>'neutral','name'=>'Neutral']], ['id','name'], 'Gender', $voice['gender'] ?? 'neutral'); ?></div><div class="col-md-4"><?php echo render_input('provider_voice_id', 'Provider Voice ID', $voice['provider_voice_id'] ?? ''); ?></div></div><?php echo render_textarea('sample_text', 'Sample Text', $voice['sample_text'] ?? '', ['rows'=>4]); ?><?php echo render_select('status', [['id'=>'active','name'=>'Active'],['id'=>'inactive','name'=>'Inactive']], ['id','name'], 'Status', $voice['status'] ?? 'active'); ?><div class="text-right"><a class="btn btn-default" href="<?php echo admin_url('usi_smartchoice_seo/video_voices'); ?>">Back</a><button class="btn btn-primary" type="submit">Save Voice</button></div><?php echo form_close(); ?></div></div></div></div><?php init_tail(); ?>